import{_ as t,c as i,o as a,a2 as h}from"./chunks/framework.B7el9cAC.js";const d=JSON.parse('{"title":"Mục 3.4 – Học máy (Machine Learning)","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-3/3.4-hoc-may.md","filePath":"chuong-3/3.4-hoc-may.md","lastUpdated":1775361034000}'),o={name:"chuong-3/3.4-hoc-may.md"};function e(r,n,g,l,c,s){return a(),i("div",null,[...n[0]||(n[0]=[h('<h1 id="muc-3-4-–-hoc-may-machine-learning" tabindex="-1">Mục 3.4 – Học máy (Machine Learning) <a class="header-anchor" href="#muc-3-4-–-hoc-may-machine-learning" aria-label="Permalink to &quot;Mục 3.4 – Học máy (Machine Learning)&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p>Bạn có biết rằng <strong>email rác (spam)</strong> không bị chặn bởi một danh sách từ cấm cố định? Nó bị chặn bởi một chương trình đã <strong>tự học</strong> từ hàng triệu email mà người dùng đã đánh dấu là spam. Chương trình đó là một ví dụ điển hình của <strong>học máy</strong>.</p><p><strong>Học máy là gì theo nghĩa đơn giản nhất?</strong> Thay vì lập trình cứng từng quy tắc (&quot;nếu email có từ &#39;trúng thưởng&#39; thì chặn&quot;), bạn cho máy tính <strong>tự rút ra quy tắc</strong> từ dữ liệu mẫu. Máy tính &quot;học&quot; như một học sinh — xem ví dụ, nhận ra mẫu, rồi áp dụng vào trường hợp mới.</p><p><strong>Ví dụ đời thực:</strong></p><ul><li>🏠 <strong>Tại nhà:</strong> Camera an ninh học nhận diện thành viên gia đình, tự cảnh báo khi có người lạ.</li><li>☕ <strong>Tại quán cafe:</strong> Hệ thống POS dự đoán nguyên liệu cần nhập kho dựa trên lịch sử bán hàng.</li><li>🏫 <strong>Tại trường:</strong> Phần mềm phát hiện đạo văn học mẫu văn bản của từng học sinh để nhận ra bất thường.</li></ul><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="hoc-may-machine-learning-la-gi" tabindex="-1">Học máy (Machine Learning) là gì? <a class="header-anchor" href="#hoc-may-machine-learning-la-gi" aria-label="Permalink to &quot;Học máy (Machine Learning) là gì?&quot;">​</a></h3><p><strong>Học máy (Machine Learning – ML)</strong> là nhánh của AI cho phép máy tính <strong>tự cải thiện hiệu năng</strong> thông qua kinh nghiệm (dữ liệu) mà <strong>không cần lập trình tường minh</strong> cho từng tình huống cụ thể.</p><p>Thay vì:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lập trình viên viết quy tắc → Máy tính áp dụng quy tắc → Kết quả</span></span></code></pre></div><p>Học máy làm:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Dữ liệu + Kết quả mong muốn → Thuật toán học → Quy tắc (mô hình) → Áp dụng cho dữ liệu mới</span></span></code></pre></div><h3 id="ba-loai-hoc-may-chinh" tabindex="-1">Ba loại học máy chính <a class="header-anchor" href="#ba-loai-hoc-may-chinh" aria-label="Permalink to &quot;Ba loại học máy chính&quot;">​</a></h3><h4 id="_1-hoc-co-giam-sat-supervised-learning" tabindex="-1">1. Học có giám sát (Supervised Learning) <a class="header-anchor" href="#_1-hoc-co-giam-sat-supervised-learning" aria-label="Permalink to &quot;1. Học có giám sát (Supervised Learning)&quot;">​</a></h4><ul><li><strong>Đặc điểm:</strong> Dữ liệu huấn luyện có nhãn (đã biết đúng/sai)</li><li><strong>Cách học:</strong> Máy học từ cặp (đầu vào → đầu ra mong muốn) đã biết</li><li><strong>Ví dụ:</strong> Nhận diện ảnh chó/mèo khi đã có 10.000 ảnh được gán nhãn sẵn</li><li><strong>Ứng dụng thực tế:</strong> Lọc spam, dự đoán giá nhà, chẩn đoán bệnh qua ảnh X-quang</li></ul><h4 id="_2-hoc-khong-giam-sat-unsupervised-learning" tabindex="-1">2. Học không giám sát (Unsupervised Learning) <a class="header-anchor" href="#_2-hoc-khong-giam-sat-unsupervised-learning" aria-label="Permalink to &quot;2. Học không giám sát (Unsupervised Learning)&quot;">​</a></h4><ul><li><strong>Đặc điểm:</strong> Dữ liệu không có nhãn</li><li><strong>Cách học:</strong> Máy tự tìm ra cấu trúc, nhóm, mẫu ẩn trong dữ liệu</li><li><strong>Ví dụ:</strong> Nhóm khách hàng theo hành vi mua sắm mà không biết trước nhóm là gì</li><li><strong>Ứng dụng thực tế:</strong> Phân đoạn thị trường, phát hiện gian lận tài chính, nén dữ liệu</li></ul><h4 id="_3-hoc-tang-cuong-reinforcement-learning" tabindex="-1">3. Học tăng cường (Reinforcement Learning) <a class="header-anchor" href="#_3-hoc-tang-cuong-reinforcement-learning" aria-label="Permalink to &quot;3. Học tăng cường (Reinforcement Learning)&quot;">​</a></h4><ul><li><strong>Đặc điểm:</strong> Máy học qua thử và sai, nhận điểm thưởng/phạt</li><li><strong>Cách học:</strong> Giống như dạy con chó bằng phần thưởng — làm đúng được thưởng, làm sai bị phạt</li><li><strong>Ví dụ:</strong> AI học chơi cờ vua bằng cách tự chơi hàng triệu ván, thắng được điểm thưởng</li><li><strong>Ứng dụng thực tế:</strong> AlphaGo (cờ vây), xe tự lái học cách điều hướng, robot học cách đi đứng</li></ul><h3 id="qua-trinh-hoc-cua-may" tabindex="-1">Quá trình học của máy <a class="header-anchor" href="#qua-trinh-hoc-cua-may" aria-label="Permalink to &quot;Quá trình học của máy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Bước</th><th>Tên</th><th>Mô tả</th></tr></thead><tbody><tr><td>1</td><td>Thu thập dữ liệu</td><td>Tập hợp dữ liệu huấn luyện có chất lượng</td></tr><tr><td>2</td><td>Tiền xử lý</td><td>Làm sạch, chuẩn hóa, loại bỏ nhiễu</td></tr><tr><td>3</td><td>Chọn mô hình</td><td>Chọn thuật toán phù hợp với bài toán</td></tr><tr><td>4</td><td>Huấn luyện</td><td>Chạy thuật toán trên dữ liệu để học tham số</td></tr><tr><td>5</td><td>Đánh giá</td><td>Kiểm tra độ chính xác trên dữ liệu chưa thấy</td></tr><tr><td>6</td><td>Tinh chỉnh</td><td>Điều chỉnh để cải thiện kết quả</td></tr><tr><td>7</td><td>Triển khai</td><td>Đưa mô hình vào sử dụng thực tế</td></tr></tbody></table><h3 id="deep-learning-hoc-sau-la-gi" tabindex="-1">Deep Learning (Học sâu) là gì? <a class="header-anchor" href="#deep-learning-hoc-sau-la-gi" aria-label="Permalink to &quot;Deep Learning (Học sâu) là gì?&quot;">​</a></h3><p><strong>Deep Learning</strong> là nhánh nâng cao của học máy sử dụng <strong>mạng nơ-ron nhân tạo</strong> nhiều lớp (deep neural networks), lấy cảm hứng từ cách não người hoạt động.</p><ul><li><strong>Điểm mạnh:</strong> Rất hiệu quả với dữ liệu phức tạp như ảnh, âm thanh, văn bản</li><li><strong>Điểm yếu:</strong> Cần lượng dữ liệu và sức mạnh tính toán rất lớn</li><li><strong>Ứng dụng:</strong> Nhận diện giọng nói (Siri), dịch ngôn ngữ (Google Dịch), tạo ảnh từ văn bản</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="hoc-may-hoat-đong-nhu-the-nao-thuc-su" tabindex="-1">Học máy hoạt động như thế nào thực sự? <a class="header-anchor" href="#hoc-may-hoat-đong-nhu-the-nao-thuc-su" aria-label="Permalink to &quot;Học máy hoạt động như thế nào thực sự?&quot;">​</a></h3><p>Hãy tưởng tượng bạn đang học nhận biết trái cây:</p><ol><li><strong>Dữ liệu:</strong> Bạn được xem 1.000 ảnh táo (gán nhãn &quot;táo&quot;) và 1.000 ảnh cam (gán nhãn &quot;cam&quot;)</li><li><strong>Đặc trưng:</strong> Não bạn tự học ra: táo = tròn + đỏ/xanh lá + cuống nhỏ, cam = tròn + cam + vỏ sần</li><li><strong>Mô hình:</strong> Bộ quy tắc ngầm định hình thành trong não</li><li><strong>Dự đoán:</strong> Khi thấy quả mới, não áp dụng quy tắc đã học → nhận ra đó là táo hay cam</li></ol><p><strong>Máy tính làm y như vậy</strong> — nhưng thay vì não người, đó là ma trận số và phép tính toán học. Những &quot;đặc trưng&quot; máy học ra không phải là từ ngữ mô tả mà là <strong>các con số đặc trưng</strong> (feature vectors).</p><h3 id="tai-sao-can-nhieu-du-lieu" tabindex="-1">Tại sao cần nhiều dữ liệu? <a class="header-anchor" href="#tai-sao-can-nhieu-du-lieu" aria-label="Permalink to &quot;Tại sao cần nhiều dữ liệu?&quot;">​</a></h3><p>Giống như một học sinh cần làm nhiều bài tập để giỏi — máy cần nhiều ví dụ để nhận ra mẫu chính xác. Nếu chỉ thấy 5 ảnh chó, máy có thể nghĩ &quot;chó = con vật màu nâu&quot; — cho đến khi thấy chó trắng thì nhầm.</p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="huan-luyen-mo-hinh-nhan-dien-spam" tabindex="-1">Huấn luyện mô hình nhận diện spam <a class="header-anchor" href="#huan-luyen-mo-hinh-nhan-dien-spam" aria-label="Permalink to &quot;Huấn luyện mô hình nhận diện spam&quot;">​</a></h3><ol><li><strong>Thu thập dữ liệu:</strong> 10.000 email đã được gán nhãn: 5.000 spam, 5.000 không spam</li><li><strong>Trích xuất đặc trưng:</strong> Đếm tần suất từ, địa chỉ người gửi, có link không, có file đính kèm không</li><li><strong>Huấn luyện:</strong> Thuật toán học phân biệt email spam dựa trên các đặc trưng đó</li><li><strong>Kiểm tra:</strong> Thử với 1.000 email chưa thấy — đạt 95% chính xác</li><li><strong>Triển khai:</strong> Tích hợp vào hệ thống email</li><li><strong>Cập nhật liên tục:</strong> Khi người dùng đánh dấu spam mới → dữ liệu mới → mô hình được tái huấn luyện</li></ol><h3 id="xe-tu-lai-hoc-lai-xe" tabindex="-1">Xe tự lái học lái xe <a class="header-anchor" href="#xe-tu-lai-hoc-lai-xe" aria-label="Permalink to &quot;Xe tự lái học lái xe&quot;">​</a></h3><ol><li><strong>Thu thập dữ liệu:</strong> Hàng triệu giờ video lái xe với quyết định của tài xế người</li><li><strong>Nhận diện đặc trưng:</strong> Làn đường, biển báo, phương tiện khác, người đi bộ</li><li><strong>Học quyết định:</strong> Khi nào tăng tốc, phanh, rẽ, nhường đường</li><li><strong>Thử nghiệm ảo:</strong> Mô phỏng hàng triệu tình huống nguy hiểm trong máy tính</li><li><strong>Thử nghiệm thực tế:</strong> Chạy thật trên đường có giám sát</li><li><strong>Cải thiện liên tục:</strong> Tai nạn/tình huống bất ngờ → học từ lỗi → cải thiện</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-du-đoan-thoi-tiet" tabindex="-1">Ví dụ 1 – Cơ bản: Dự đoán thời tiết <a class="header-anchor" href="#vi-du-1-–-co-ban-du-đoan-thoi-tiet" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Dự đoán thời tiết&quot;">​</a></h3><p>Mô hình học máy được huấn luyện với 30 năm dữ liệu thời tiết (nhiệt độ, độ ẩm, áp suất không khí, lượng mưa hôm trước…) và thời tiết thực tế hôm sau. Sau khi học, nó có thể dự đoán: &quot;Ngày mai có 78% khả năng mưa&quot; dựa trên điều kiện thời tiết hôm nay.</p><h3 id="vi-du-2-–-đoi-thuc-spotify-goi-y-nhac" tabindex="-1">Ví dụ 2 – Đời thực: Spotify gợi ý nhạc <a class="header-anchor" href="#vi-du-2-–-đoi-thuc-spotify-goi-y-nhac" aria-label="Permalink to &quot;Ví dụ 2 – Đời thực: Spotify gợi ý nhạc&quot;">​</a></h3><p>Spotify dùng học máy để:</p><ul><li>Phân tích âm học của bài nhạc (nhịp điệu, nhạc cụ, tempo, tông giọng)</li><li>So sánh sở thích của bạn với hàng triệu người dùng khác</li><li>Dự đoán bài hát nào bạn sẽ thích nhất</li></ul><p>→ Playlist &quot;Discover Weekly&quot; mỗi thứ Hai chính là kết quả của hàng triệu phép tính học máy.</p><h3 id="vi-du-3-–-nang-cao-alphago-đanh-bai-nha-vo-đich-co-vay" tabindex="-1">Ví dụ 3 – Nâng cao: AlphaGo đánh bại nhà vô địch cờ vây <a class="header-anchor" href="#vi-du-3-–-nang-cao-alphago-đanh-bai-nha-vo-đich-co-vay" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: AlphaGo đánh bại nhà vô địch cờ vây&quot;">​</a></h3><p>AlphaGo của Google DeepMind dùng <strong>học tăng cường</strong>:</p><ul><li>Ban đầu học từ hàng triệu ván cờ của người chơi</li><li>Sau đó tự chơi hàng triệu ván với chính mình</li><li>Mỗi nước đi thắng → điểm thưởng, nước đi thua → điểm phạt</li><li>Sau hàng tỷ lần thử, AlphaGo tìm ra các chiến thuật mà <strong>chưa người chơi cờ nào từng nghĩ ra</strong></li><li>Năm 2016, AlphaGo đánh bại Lee Sedol — nhà vô địch cờ vây thế giới — 4-1</li></ul><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="ba-loai-hoc-may" tabindex="-1">Ba loại học máy <a class="header-anchor" href="#ba-loai-hoc-may" aria-label="Permalink to &quot;Ba loại học máy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Học có giám sát</th><th>Học không giám sát</th><th>Học tăng cường</th></tr></thead><tbody><tr><td>Dữ liệu</td><td>Có nhãn (labeled)</td><td>Không nhãn (unlabeled)</td><td>Phản hồi thưởng/phạt</td></tr><tr><td>Mục tiêu</td><td>Dự đoán/phân loại</td><td>Tìm cấu trúc/nhóm</td><td>Tối đa hóa phần thưởng</td></tr><tr><td>Ví dụ</td><td>Lọc spam, chẩn đoán bệnh</td><td>Phân nhóm khách hàng</td><td>AlphaGo, xe tự lái</td></tr><tr><td>Khó khăn</td><td>Cần nhiều dữ liệu có nhãn (tốn công gán)</td><td>Khó đánh giá kết quả</td><td>Cần nhiều vòng thử</td></tr></tbody></table><h3 id="machine-learning-vs-deep-learning-vs-ai" tabindex="-1">Machine Learning vs Deep Learning vs AI <a class="header-anchor" href="#machine-learning-vs-deep-learning-vs-ai" aria-label="Permalink to &quot;Machine Learning vs Deep Learning vs AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Khái niệm</th><th>Mô tả</th><th>Phạm vi</th></tr></thead><tbody><tr><td>AI (Trí tuệ nhân tạo)</td><td>Khái niệm rộng — máy làm việc đòi hỏi trí tuệ người</td><td>Rộng nhất</td></tr><tr><td>Machine Learning (Học máy)</td><td>AI học từ dữ liệu</td><td>Nằm trong AI</td></tr><tr><td>Deep Learning (Học sâu)</td><td>ML dùng mạng nơ-ron nhiều lớp</td><td>Nằm trong ML</td></tr></tbody></table><p><em>Hình ảnh tóm tắt:</em> AI ⊃ Machine Learning ⊃ Deep Learning</p><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li><strong>Học máy (ML)</strong> = máy tính tự học từ dữ liệu, không cần lập trình từng quy tắc cụ thể</li><li><strong>Học có giám sát</strong> = dữ liệu có nhãn → học phân loại/dự đoán (spam, chẩn đoán bệnh)</li><li><strong>Học không giám sát</strong> = dữ liệu không nhãn → tự tìm cấu trúc/nhóm (phân khúc khách hàng)</li><li><strong>Học tăng cường</strong> = học qua thử và sai, tối đa phần thưởng (AlphaGo, xe tự lái)</li><li><strong>Deep Learning</strong> = ML với mạng nơ-ron nhiều lớp, hiệu quả với ảnh/âm thanh/văn bản</li><li><strong>Mô hình</strong> = bộ quy tắc/tham số mà máy học được từ dữ liệu</li><li>Học máy cần <strong>dữ liệu nhiều và chất lượng</strong> — dữ liệu xấu → mô hình xấu</li><li>AI ⊃ Machine Learning ⊃ Deep Learning (học sâu là tập con của học máy)</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><p><strong>Câu 1 (Dễ):</strong> Phân biệt &quot;lập trình truyền thống&quot; và &quot;học máy&quot; theo cách tiếp cận giải quyết vấn đề.</p><blockquote><p><strong>Đáp án:</strong></p><ul><li><strong>Lập trình truyền thống:</strong> Lập trình viên viết tường minh từng quy tắc → Máy tính áp dụng → Ra kết quả.</li><li><strong>Học máy:</strong> Cung cấp dữ liệu có kết quả đã biết → Thuật toán tự học quy tắc → Áp dụng cho dữ liệu mới.</li><li><strong>Điểm khác biệt:</strong> Học máy không cần biết trước quy tắc — máy tự tìm ra.</li></ul></blockquote><hr><p><strong>Câu 2 (Dễ):</strong> Cho ba ứng dụng sau, hãy xác định loại học máy phù hợp nhất cho mỗi ứng dụng: (a) phân loại email spam, (b) tìm nhóm khách hàng tương tự nhau, (c) huấn luyện robot đi trong mê cung.</p><blockquote><p><strong>Đáp án:</strong></p><ul><li>(a) <strong>Học có giám sát</strong> — có dữ liệu mẫu đã gán nhãn spam/không spam.</li><li>(b) <strong>Học không giám sát</strong> — không biết trước các nhóm, máy tự tìm cấu trúc.</li><li>(c) <strong>Học tăng cường</strong> — robot học qua thử sai, đến đích được thưởng, đâm tường bị phạt.</li></ul></blockquote><hr><p><strong>Câu 3 (Trung bình):</strong> Mô tả 4 bước cơ bản trong quá trình xây dựng một mô hình học máy.</p><blockquote><p><strong>Đáp án:</strong></p><ol><li><strong>Thu thập và tiền xử lý dữ liệu:</strong> Tập hợp dữ liệu, làm sạch, chuẩn hóa.</li><li><strong>Chọn và huấn luyện mô hình:</strong> Chọn thuật toán phù hợp, chạy trên dữ liệu huấn luyện.</li><li><strong>Đánh giá mô hình:</strong> Kiểm tra độ chính xác trên dữ liệu chưa thấy (test set).</li><li><strong>Tinh chỉnh và triển khai:</strong> Điều chỉnh tham số cho tốt hơn, rồi đưa vào sử dụng thực tế.</li></ol></blockquote><hr><p><strong>Câu 4 (Trung bình):</strong> Tại sao chất lượng dữ liệu huấn luyện lại quan trọng trong học máy? Cho ví dụ về tác hại của dữ liệu kém chất lượng.</p><blockquote><p><strong>Đáp án:</strong> Mô hình học máy chỉ tốt bằng dữ liệu nó học từ đó — &quot;garbage in, garbage out&quot;. Ví dụ: Một hệ thống nhận diện khuôn mặt được huấn luyện chủ yếu trên ảnh người da trắng sẽ nhận diện kém hơn với người da đen — vì dữ liệu không đa dạng. Dữ liệu thiên vị → mô hình thiên vị → kết quả phân biệt đối xử.</p></blockquote><hr><p><strong>Câu 5 (Ứng dụng):</strong> Một bệnh viện muốn dùng học máy để chẩn đoán sớm bệnh tiểu đường từ kết quả xét nghiệm máu. Hãy mô tả: (a) loại học máy phù hợp, (b) dữ liệu cần thu thập, (c) một rủi ro cần lưu ý.</p><blockquote><p><strong>Đáp án gợi ý:</strong></p><ul><li><strong>(a) Học có giám sát:</strong> Vì có dữ liệu lịch sử bệnh nhân (kết quả xét nghiệm + chẩn đoán thực tế của bác sĩ).</li><li><strong>(b) Dữ liệu cần thu thập:</strong> Chỉ số đường huyết, HbA1c, BMI, tuổi, tiền sử gia đình, kết quả xét nghiệm khác + nhãn &quot;có/không có tiểu đường&quot; do bác sĩ xác nhận.</li><li><strong>(c) Rủi ro:</strong> Mô hình có thể cho kết quả dương tính giả (chẩn đoán nhầm bệnh) hoặc âm tính giả (bỏ sót bệnh). Cần bác sĩ xem xét kết quả AI — không được để AI ra quyết định y tế độc lập.</li></ul></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nghi-machine-learning-la-may-tinh-tu-lap-trinh" tabindex="-1">❌ Lỗi 1: Nghĩ machine learning là máy tính &quot;tự lập trình&quot; <a class="header-anchor" href="#❌-loi-1-nghi-machine-learning-la-may-tinh-tu-lap-trinh" aria-label="Permalink to &quot;❌ Lỗi 1: Nghĩ machine learning là máy tính &quot;tự lập trình&quot;&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Machine learning là máy tính tự viết code cho chính nó.&quot;</p><p><strong>Đúng:</strong> ML là máy tính điều chỉnh tham số (parameters) dựa trên dữ liệu để tối ưu hóa hàm mục tiêu. Code (kiến trúc mô hình) do kỹ sư viết, máy tự điều chỉnh weights. Không phải &quot;tự lập trình&quot; mà là tự tối ưu trong framework đã định.</p><hr><h3 id="❌-loi-2-nham-training-data-voi-test-data" tabindex="-1">❌ Lỗi 2: Nhầm training data với test data <a class="header-anchor" href="#❌-loi-2-nham-training-data-voi-test-data" aria-label="Permalink to &quot;❌ Lỗi 2: Nhầm training data với test data&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng toàn bộ dữ liệu để train thì model sẽ tốt nhất.&quot;</p><p><strong>Đúng:</strong> Phải tách dữ liệu: training set (để train), validation set (điều chỉnh hyperparameters), test set (đánh giá cuối cùng, chỉ dùng một lần). Dùng hết data để train → không biết model hoạt động thế nào với dữ liệu mới (overfitting không phát hiện được).</p><hr><h3 id="❌-loi-3-nghi-accuracy-cao-luon-nghia-la-model-tot" tabindex="-1">❌ Lỗi 3: Nghĩ accuracy cao luôn nghĩa là model tốt <a class="header-anchor" href="#❌-loi-3-nghi-accuracy-cao-luon-nghia-la-model-tot" aria-label="Permalink to &quot;❌ Lỗi 3: Nghĩ accuracy cao luôn nghĩa là model tốt&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Model đạt 99% accuracy là model tốt.&quot;</p><p><strong>Đúng:</strong> Với dữ liệu mất cân bằng (99% negative, 1% positive), model luôn dự đoán negative đạt 99% accuracy nhưng vô dụng. Cần xem F1-score, AUC-ROC, precision-recall curve tùy bài toán. Ví dụ: phát hiện gian lận thẻ tín dụng cần recall cao dù precision thấp hơn.</p><hr><h3 id="❌-loi-4-nham-overfitting-voi-underfitting" tabindex="-1">❌ Lỗi 4: Nhầm overfitting với underfitting <a class="header-anchor" href="#❌-loi-4-nham-overfitting-voi-underfitting" aria-label="Permalink to &quot;❌ Lỗi 4: Nhầm overfitting với underfitting&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Model học nhiều hơn luôn tốt hơn.&quot;</p><p><strong>Đúng:</strong> Overfitting: model học quá kỹ training data, bao gồm cả noise, kém với data mới (high variance). Underfitting: model quá đơn giản, không học được pattern (high bias). Mục tiêu là tìm điểm cân bằng – bias-variance tradeoff. Regularization, cross-validation giúp tránh overfitting.</p><hr><h3 id="❌-loi-5-cho-rang-deep-learning-luon-tot-hon-classical-ml" tabindex="-1">❌ Lỗi 5: Cho rằng deep learning luôn tốt hơn classical ML <a class="header-anchor" href="#❌-loi-5-cho-rang-deep-learning-luon-tot-hon-classical-ml" aria-label="Permalink to &quot;❌ Lỗi 5: Cho rằng deep learning luôn tốt hơn classical ML&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Deep learning mới nhất nên luôn tốt hơn Random Forest hay SVM.&quot;</p><p><strong>Đúng:</strong> Không có mô hình tốt nhất cho mọi bài toán (No Free Lunch theorem). Deep learning tỏa sáng với: dữ liệu lớn, hình ảnh/văn bản/âm thanh. Classical ML (Random Forest, Gradient Boosting) thường tốt hơn với: dữ liệu tabular có ít features, dữ liệu ít, và cần interpretability.</p><hr><h3 id="❌-loi-6-nghi-du-lieu-nhieu-hon-luon-tot-hon" tabindex="-1">❌ Lỗi 6: Nghĩ dữ liệu nhiều hơn luôn tốt hơn <a class="header-anchor" href="#❌-loi-6-nghi-du-lieu-nhieu-hon-luon-tot-hon" aria-label="Permalink to &quot;❌ Lỗi 6: Nghĩ dữ liệu nhiều hơn luôn tốt hơn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Càng nhiều dữ liệu thì model càng tốt.&quot;</p><p><strong>Đúng:</strong> Dữ liệu chất lượng quan trọng hơn số lượng. 1 triệu ảnh xấu (mờ, label sai) kém hơn 100.000 ảnh tốt, label đúng. &quot;Garbage in, garbage out.&quot; Ngoài ra, dữ liệu thừa tăng chi phí tính toán mà không tăng performance. Data curation (làm sạch, chọn lọc) là bước quan trọng.</p><hr><h3 id="❌-loi-7-nham-feature-va-label" tabindex="-1">❌ Lỗi 7: Nhầm feature và label <a class="header-anchor" href="#❌-loi-7-nham-feature-va-label" aria-label="Permalink to &quot;❌ Lỗi 7: Nhầm feature và label&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Feature và label đều là dữ liệu đầu vào.&quot;</p><p><strong>Đúng:</strong> Feature (hay input): các thuộc tính dùng để dự đoán (ví dụ: diện tích nhà, số phòng ngủ). Label (hay target/output): giá trị cần dự đoán (ví dụ: giá nhà). Supervised learning học ánh xạ từ features → label. Label chỉ có trong training data, không có khi deploy.</p><hr><h3 id="❌-loi-8-cho-rang-cross-validation-chi-dung-đe-kiem-tra" tabindex="-1">❌ Lỗi 8: Cho rằng cross-validation chỉ dùng để kiểm tra <a class="header-anchor" href="#❌-loi-8-cho-rang-cross-validation-chi-dung-đe-kiem-tra" aria-label="Permalink to &quot;❌ Lỗi 8: Cho rằng cross-validation chỉ dùng để kiểm tra&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Cross-validation chỉ cần dùng khi muốn kiểm tra model cuối cùng.&quot;</p><p><strong>Đúng:</strong> Cross-validation dùng trong quá trình training để: chọn hyperparameters tốt nhất, so sánh các thuật toán khác nhau, và ước tính performance trên data mới một cách ổn định hơn single train/test split. Là phần thiết yếu của pipeline ML.</p><hr><h3 id="❌-loi-9-nghi-neural-network-đuoc-lay-cam-hung-y-het-tu-nao-nguoi" tabindex="-1">❌ Lỗi 9: Nghĩ neural network được lấy cảm hứng y hệt từ não người <a class="header-anchor" href="#❌-loi-9-nghi-neural-network-đuoc-lay-cam-hung-y-het-tu-nao-nguoi" aria-label="Permalink to &quot;❌ Lỗi 9: Nghĩ neural network được lấy cảm hứng y hệt từ não người&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Neural network mô phỏng chính xác cách não người hoạt động.&quot;</p><p><strong>Đúng:</strong> Neural network lấy cảm hứng lỏng lẻo từ não người. Artificial neuron là mô hình toán học đơn giản hóa rất nhiều so với biological neuron thật. Não người: 86 tỷ neuron, kết nối analog, học liên tục, sử dụng ít năng lượng. ANN: triệu-tỷ parameters, kết nối số, batch learning, tốn nhiều điện.</p><hr><h3 id="❌-loi-10-nham-supervised-learning-voi-semi-supervised-learning" tabindex="-1">❌ Lỗi 10: Nhầm supervised learning với semi-supervised learning <a class="header-anchor" href="#❌-loi-10-nham-supervised-learning-voi-semi-supervised-learning" aria-label="Permalink to &quot;❌ Lỗi 10: Nhầm supervised learning với semi-supervised learning&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Nếu không có đủ label, phải dùng supervised learning với ít data.&quot;</p><p><strong>Đúng:</strong> Semi-supervised learning dùng một ít labeled data + nhiều unlabeled data – thường hiệu quả hơn supervised learning với ít data. Đây là giải pháp thực tế vì labeling (gán nhãn) tốn kém. Ví dụ: label 1000 ảnh + dùng 100.000 ảnh không có label.</p><hr><h3 id="❌-loi-11-cho-rang-hyperparameter-la-thu-model-tu-hoc" tabindex="-1">❌ Lỗi 11: Cho rằng hyperparameter là thứ model tự học <a class="header-anchor" href="#❌-loi-11-cho-rang-hyperparameter-la-thu-model-tu-hoc" aria-label="Permalink to &quot;❌ Lỗi 11: Cho rằng hyperparameter là thứ model tự học&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Model tự tối ưu hóa tất cả parameters và hyperparameters.&quot;</p><p><strong>Đúng:</strong> Model tự học parameters (weights, biases) qua gradient descent. Hyperparameters (learning rate, số lớp, batch size...) là do người thiết lập và không tự học. Chọn hyperparameters tốt cần: grid search, random search, hay Bayesian optimization – là kỹ thuật riêng ngoài training.</p><hr><h3 id="❌-loi-12-nghi-loss-function-luon-la-mean-squared-error" tabindex="-1">❌ Lỗi 12: Nghĩ loss function luôn là mean squared error <a class="header-anchor" href="#❌-loi-12-nghi-loss-function-luon-la-mean-squared-error" aria-label="Permalink to &quot;❌ Lỗi 12: Nghĩ loss function luôn là mean squared error&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Hàm loss chuẩn cho mọi bài toán là MSE (Mean Squared Error).&quot;</p><p><strong>Đúng:</strong> Chọn loss function phụ thuộc bài toán: MSE tốt cho regression. Cross-entropy cho classification. Focal loss cho imbalanced classification. Huber loss cho regression với outliers. IoU loss cho object detection. Chọn sai loss function → model tối ưu cho metric sai.</p><hr><h3 id="❌-loi-13-nham-epoch-voi-batch-voi-iteration" tabindex="-1">❌ Lỗi 13: Nhầm epoch với batch với iteration <a class="header-anchor" href="#❌-loi-13-nham-epoch-voi-batch-voi-iteration" aria-label="Permalink to &quot;❌ Lỗi 13: Nhầm epoch với batch với iteration&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Epoch, batch, và iteration là ba tên cho cùng một khái niệm.&quot;</p><p><strong>Đúng:</strong> Batch: tập hợp nhỏ của training data xử lý cùng lúc. Iteration: một lần cập nhật weights (dùng một batch). Epoch: một lần đi qua toàn bộ training data. Ví dụ: 1000 samples, batch size 100 → 10 iterations = 1 epoch. Training thường chạy nhiều epoch.</p><hr><h3 id="❌-loi-14-cho-rang-learning-rate-khong-quan-trong" tabindex="-1">❌ Lỗi 14: Cho rằng learning rate không quan trọng <a class="header-anchor" href="#❌-loi-14-cho-rang-learning-rate-khong-quan-trong" aria-label="Permalink to &quot;❌ Lỗi 14: Cho rằng learning rate không quan trọng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Learning rate chỉ là một con số nhỏ, không cần chú ý nhiều.&quot;</p><p><strong>Đúng:</strong> Learning rate là một trong các hyperparameter quan trọng nhất: quá lớn → training không hội tụ (diverge), nhảy qua minimum. Quá nhỏ → training cực kỳ chậm, có thể mắc kẹt ở local minimum. Learning rate scheduling (giảm dần theo thời gian) là kỹ thuật phổ biến.</p><hr><h3 id="❌-loi-15-nghi-gradient-descent-luon-tim-đuoc-global-minimum" tabindex="-1">❌ Lỗi 15: Nghĩ gradient descent luôn tìm được global minimum <a class="header-anchor" href="#❌-loi-15-nghi-gradient-descent-luon-tim-đuoc-global-minimum" aria-label="Permalink to &quot;❌ Lỗi 15: Nghĩ gradient descent luôn tìm được global minimum&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Gradient descent luôn tìm được giải pháp tốt nhất tuyệt đối (global minimum).&quot;</p><p><strong>Đúng:</strong> Gradient descent tìm local minimum, không đảm bảo global minimum. Với deep learning, loss landscape cực kỳ phức tạp với nhiều local minima và saddle points. Thực tế, local minima tốt trong deep learning thường đủ tốt cho ứng dụng thực tế.</p><hr><h3 id="❌-loi-16-nham-regularization-voi-normalization" tabindex="-1">❌ Lỗi 16: Nhầm regularization với normalization <a class="header-anchor" href="#❌-loi-16-nham-regularization-voi-normalization" aria-label="Permalink to &quot;❌ Lỗi 16: Nhầm regularization với normalization&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Regularization và normalization đều là kỹ thuật chuẩn hóa dữ liệu.&quot;</p><p><strong>Đúng:</strong> Normalization (hay data preprocessing): chuẩn hóa features để có cùng thang đo (min-max, z-score). Regularization: kỹ thuật tránh overfitting bằng cách phạt model phức tạp quá (L1/L2 regularization, dropout). Hai kỹ thuật khác nhau hoàn toàn về mục đích.</p><hr><h3 id="❌-loi-17-cho-rang-ai-nhan-dien-anh-nhin-thay-nhu-con-nguoi" tabindex="-1">❌ Lỗi 17: Cho rằng AI nhận diện ảnh &quot;nhìn thấy&quot; như con người <a class="header-anchor" href="#❌-loi-17-cho-rang-ai-nhan-dien-anh-nhin-thay-nhu-con-nguoi" aria-label="Permalink to &quot;❌ Lỗi 17: Cho rằng AI nhận diện ảnh &quot;nhìn thấy&quot; như con người&quot;">​</a></h3><p><strong>Sai:</strong> &quot;CNN nhận diện ảnh bằng cách nhìn vào ảnh như mắt người.&quot;</p><p><strong>Đúng:</strong> CNN xử lý ảnh qua nhiều lớp convolution tính toán activation maps – phát hiện edges, textures, patterns từ thấp đến cao. Không có &quot;nhìn thấy&quot; theo nghĩa nhận thức. Adversarial attacks chứng minh: thêm vài pixel không thể thấy được khiến CNN phân loại sai hoàn toàn – điều không xảy ra với con người.</p><hr><h3 id="❌-loi-18-nghi-transfer-learning-chi-dung-đuoc-trong-deep-learning" tabindex="-1">❌ Lỗi 18: Nghĩ transfer learning chỉ dùng được trong deep learning <a class="header-anchor" href="#❌-loi-18-nghi-transfer-learning-chi-dung-đuoc-trong-deep-learning" aria-label="Permalink to &quot;❌ Lỗi 18: Nghĩ transfer learning chỉ dùng được trong deep learning&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Transfer learning là kỹ thuật chỉ của deep learning.&quot;</p><p><strong>Đúng:</strong> Transfer learning là khái niệm tổng quát: dùng kiến thức từ task/domain đã học cho task/domain mới. Áp dụng cả trong classical ML (ví dụ: dùng pretrained word embeddings cho NLP task mới) và deep learning (fine-tune ImageNet pretrained model). Phổ biến nhất trong deep learning.</p><hr><h3 id="❌-loi-19-nham-precision-va-recall-cao-cung-luc-la-de-đat" tabindex="-1">❌ Lỗi 19: Nhầm precision và recall cao cùng lúc là dễ đạt <a class="header-anchor" href="#❌-loi-19-nham-precision-va-recall-cao-cung-luc-la-de-đat" aria-label="Permalink to &quot;❌ Lỗi 19: Nhầm precision và recall cao cùng lúc là dễ đạt&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mô hình tốt phải đạt cả precision cao và recall cao.&quot;</p><p><strong>Đúng:</strong> Precision và Recall thường có tradeoff. Tăng recall thường giảm precision và ngược lại. Phụ thuộc ứng dụng nên ưu tiên cái nào: phát hiện ung thư (recall quan trọng hơn – không bỏ sót ca bệnh), lọc spam (precision quan trọng hơn – không nhầm email thật là spam).</p><hr><h3 id="❌-loi-20-cho-rang-mot-model-ml-khong-bao-gio-can-cap-nhat" tabindex="-1">❌ Lỗi 20: Cho rằng một model ML không bao giờ cần cập nhật <a class="header-anchor" href="#❌-loi-20-cho-rang-mot-model-ml-khong-bao-gio-can-cap-nhat" aria-label="Permalink to &quot;❌ Lỗi 20: Cho rằng một model ML không bao giờ cần cập nhật&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Đã train model tốt rồi, deploy xong không cần update nữa.&quot;</p><p><strong>Đúng:</strong> Dữ liệu thực tế thay đổi theo thời gian (concept drift, data drift) làm model degradation. Ví dụ: model dự đoán hành vi mua hàng sẽ kém hiệu quả sau đại dịch COVID vì pattern tiêu dùng thay đổi. Cần monitoring liên tục và retraining định kỳ.</p><hr><h3 id="❌-loi-21-nghi-ensemble-method-chi-la-trung-binh-ket-qua-nhieu-model" tabindex="-1">❌ Lỗi 21: Nghĩ ensemble method chỉ là trung bình kết quả nhiều model <a class="header-anchor" href="#❌-loi-21-nghi-ensemble-method-chi-la-trung-binh-ket-qua-nhieu-model" aria-label="Permalink to &quot;❌ Lỗi 21: Nghĩ ensemble method chỉ là trung bình kết quả nhiều model&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Ensemble chỉ là lấy trung bình predictions của nhiều model.&quot;</p><p><strong>Đúng:</strong> Ensemble methods phong phú hơn: Bagging (Random Forest), Boosting (XGBoost, AdaBoost – mỗi model sửa lỗi của model trước), Stacking (meta-model học từ predictions của base models). Voting/averaging là cách đơn giản nhất nhưng không phải duy nhất.</p><hr><h3 id="❌-loi-22-nham-k-means-voi-k-nearest-neighbors-knn" tabindex="-1">❌ Lỗi 22: Nhầm K-means với K-nearest neighbors (KNN) <a class="header-anchor" href="#❌-loi-22-nham-k-means-voi-k-nearest-neighbors-knn" aria-label="Permalink to &quot;❌ Lỗi 22: Nhầm K-means với K-nearest neighbors (KNN)&quot;">​</a></h3><p><strong>Sai:</strong> &quot;K-means và KNN đều là thuật toán với K neighbors.&quot;</p><p><strong>Đúng:</strong> K-means: thuật toán clustering không giám sát – chia data thành K nhóm (K là hyperparameter người chọn). KNN (K-Nearest Neighbors): thuật toán classification/regression có giám sát – phân loại dựa trên K điểm gần nhất. Hoàn toàn khác nhau về mục đích và cách hoạt động.</p><hr><h3 id="❌-loi-23-cho-rang-model-phuc-tap-luon-tot-hon-model-đon-gian" tabindex="-1">❌ Lỗi 23: Cho rằng model phức tạp luôn tốt hơn model đơn giản <a class="header-anchor" href="#❌-loi-23-cho-rang-model-phuc-tap-luon-tot-hon-model-đon-gian" aria-label="Permalink to &quot;❌ Lỗi 23: Cho rằng model phức tạp luôn tốt hơn model đơn giản&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mạng nơ-ron 100 lớp luôn tốt hơn linear regression.&quot;</p><p><strong>Đúng:</strong> Occam&#39;s Razor trong ML: ưu tiên model đơn giản nhất đạt kết quả tốt. Model phức tạp hơn: rủi ro overfitting cao hơn, khó giải thích hơn, tốn nhiều tài nguyên hơn. Nhiều bài toán thực tế, Logistic Regression hoặc Gradient Boosting tốt hơn deep learning.</p><hr><h3 id="❌-loi-24-nghi-automl-thay-the-hoan-toan-ml-engineer" tabindex="-1">❌ Lỗi 24: Nghĩ autoML thay thế hoàn toàn ML engineer <a class="header-anchor" href="#❌-loi-24-nghi-automl-thay-the-hoan-toan-ml-engineer" aria-label="Permalink to &quot;❌ Lỗi 24: Nghĩ autoML thay thế hoàn toàn ML engineer&quot;">​</a></h3><p><strong>Sai:</strong> &quot;AutoML tự động hóa tất cả, không cần ML engineer.&quot;</p><p><strong>Đúng:</strong> AutoML tự động hóa: tìm kiếm kiến trúc, hyperparameter tuning, feature selection. Nhưng vẫn cần người: hiểu bài toán kinh doanh, thu thập và làm sạch dữ liệu, đánh giá kết quả có ý nghĩa không, triển khai và monitor. Data scientist role thay đổi, không biến mất.</p><hr><h3 id="❌-loi-25-nham-supervised-regression-voi-supervised-classification" tabindex="-1">❌ Lỗi 25: Nhầm supervised regression với supervised classification <a class="header-anchor" href="#❌-loi-25-nham-supervised-regression-voi-supervised-classification" aria-label="Permalink to &quot;❌ Lỗi 25: Nhầm supervised regression với supervised classification&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Regression và classification đều dự đoán giá trị, như nhau.&quot;</p><p><strong>Đúng:</strong> Regression: dự đoán giá trị liên tục (giá nhà, nhiệt độ). Classification: dự đoán nhãn rời rạc (spam/không spam, chó/mèo/chim). Loss functions và evaluation metrics khác nhau: MSE/RMSE cho regression; accuracy/F1/AUC cho classification.</p><hr><h3 id="❌-loi-26-cho-rang-ml-khong-can-feature-engineering" tabindex="-1">❌ Lỗi 26: Cho rằng ML không cần feature engineering <a class="header-anchor" href="#❌-loi-26-cho-rang-ml-khong-can-feature-engineering" aria-label="Permalink to &quot;❌ Lỗi 26: Cho rằng ML không cần feature engineering&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Deep learning tự học features, không cần feature engineering nữa.&quot;</p><p><strong>Đúng:</strong> Đúng với unstructured data (ảnh, văn bản). Với structured/tabular data, feature engineering vẫn rất quan trọng: tạo interaction features, xử lý missing values, encode categorical variables, và domain-specific transformations. Garbage features → garbage model.</p><hr><h3 id="❌-loi-27-nghi-model-đa-deploy-khong-the-gay-hai" tabindex="-1">❌ Lỗi 27: Nghĩ model đã deploy không thể gây hại <a class="header-anchor" href="#❌-loi-27-nghi-model-đa-deploy-khong-the-gay-hai" aria-label="Permalink to &quot;❌ Lỗi 27: Nghĩ model đã deploy không thể gây hại&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Sau khi test kỹ và deploy, model ML không gây hại được nữa.&quot;</p><p><strong>Đúng:</strong> Model trong production có thể: performance degrade theo thời gian, khuếch đại thiên kiến trong quyết định thực tế, bị adversarial attacks, hoặc gây hại khi gặp edge cases. Continuous monitoring, fairness auditing, và incident response là cần thiết.</p><hr><h3 id="❌-loi-28-nham-data-augmentation-voi-data-collection" tabindex="-1">❌ Lỗi 28: Nhầm data augmentation với data collection <a class="header-anchor" href="#❌-loi-28-nham-data-augmentation-voi-data-collection" aria-label="Permalink to &quot;❌ Lỗi 28: Nhầm data augmentation với data collection&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Thiếu dữ liệu thì dùng data augmentation thay thế thu thập thêm.&quot;</p><p><strong>Đúng:</strong> Data augmentation tạo variations của data hiện có (xoay ảnh, flip, crop, noise). Không tạo ra thông tin mới thật sự. Hữu ích để tăng diversity và regularization. Nhưng không thay thế được thu thập data thật từ domain mới. Augmentation tốt nhất bổ sung cho, không thay thế data collection.</p><hr><h3 id="❌-loi-29-cho-rang-confusion-matrix-kho-hieu-va-khong-can-thiet" tabindex="-1">❌ Lỗi 29: Cho rằng confusion matrix khó hiểu và không cần thiết <a class="header-anchor" href="#❌-loi-29-cho-rang-confusion-matrix-kho-hieu-va-khong-can-thiet" aria-label="Permalink to &quot;❌ Lỗi 29: Cho rằng confusion matrix khó hiểu và không cần thiết&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Chỉ cần nhìn accuracy là đủ, không cần confusion matrix.&quot;</p><p><strong>Đúng:</strong> Confusion matrix cho thấy: True Positive, True Negative, False Positive, False Negative – cung cấp bức tranh đầy đủ về lỗi của model. Biết loại lỗi nào mô hình mắc phải (FP hay FN) quan trọng để cải thiện đúng chỗ và đánh giá đúng rủi ro.</p><hr><h3 id="❌-loi-30-nghi-random-seed-khong-quan-trong-trong-ml" tabindex="-1">❌ Lỗi 30: Nghĩ random seed không quan trọng trong ML <a class="header-anchor" href="#❌-loi-30-nghi-random-seed-khong-quan-trong-trong-ml" aria-label="Permalink to &quot;❌ Lỗi 30: Nghĩ random seed không quan trọng trong ML&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Kết quả ML là khách quan, không phụ thuộc vào random seed.&quot;</p><p><strong>Đúng:</strong> Random seed ảnh hưởng đến: khởi tạo weights, data shuffle, train/test split... Kết quả ML có yếu tố ngẫu nhiên. Không set random seed → kết quả không reproducible. Nghiên cứu khoa học ML phải báo cáo random seed để người khác reproduce được.</p><hr><h3 id="❌-loi-31-nham-model-size-voi-model-quality" tabindex="-1">❌ Lỗi 31: Nhầm model size với model quality <a class="header-anchor" href="#❌-loi-31-nham-model-size-voi-model-quality" aria-label="Permalink to &quot;❌ Lỗi 31: Nhầm model size với model quality&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Model càng lớn (file size MB) thì càng tốt.&quot;</p><p><strong>Đúng:</strong> Model size phản ánh số tham số, không trực tiếp là quality. Model pruned (cắt tỉa) có thể nhỏ hơn nhiều mà vẫn gần bằng performance gốc. DistilBERT là 40% kích thước BERT nhưng giữ 97% performance. Hiệu quả (performance/size) quan trọng hơn size thuần túy.</p><hr><h3 id="❌-loi-32-cho-rang-ml-pipeline-khong-can-version-control" tabindex="-1">❌ Lỗi 32: Cho rằng ML pipeline không cần version control <a class="header-anchor" href="#❌-loi-32-cho-rang-ml-pipeline-khong-can-version-control" aria-label="Permalink to &quot;❌ Lỗi 32: Cho rằng ML pipeline không cần version control&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Code thì cần version control, data và model thì không cần.&quot;</p><p><strong>Đúng:</strong> MLOps hiện đại cần version control cho cả: code, data (DVC – Data Version Control), model weights, và experiments (MLflow, Weights &amp; Biases). Nếu không, không thể reproduce kết quả, không thể rollback khi model mới kém hơn, và không thể audit quyết định AI.</p><hr><h3 id="❌-loi-33-nghi-dimensionality-reduction-chi-đe-ve-đo-thi" tabindex="-1">❌ Lỗi 33: Nghĩ dimensionality reduction chỉ để vẽ đồ thị <a class="header-anchor" href="#❌-loi-33-nghi-dimensionality-reduction-chi-đe-ve-đo-thi" aria-label="Permalink to &quot;❌ Lỗi 33: Nghĩ dimensionality reduction chỉ để vẽ đồ thị&quot;">​</a></h3><p><strong>Sai:</strong> &quot;PCA và t-SNE chỉ dùng để visualize data trên 2D/3D.&quot;</p><p><strong>Đúng:</strong> Dimensionality reduction còn dùng để: giảm curse of dimensionality (model kém khi features quá nhiều so với samples), tăng tốc training, loại bỏ redundant features, và feature extraction (PCA features làm input cho classifier). Visualization chỉ là một ứng dụng.</p><hr><h3 id="❌-loi-34-nham-anomaly-detection-voi-outlier-removal" tabindex="-1">❌ Lỗi 34: Nhầm anomaly detection với outlier removal <a class="header-anchor" href="#❌-loi-34-nham-anomaly-detection-voi-outlier-removal" aria-label="Permalink to &quot;❌ Lỗi 34: Nhầm anomaly detection với outlier removal&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Phát hiện bất thường là loại bỏ outliers để data sạch hơn.&quot;</p><p><strong>Đúng:</strong> Anomaly detection là bài toán riêng: tìm điểm dữ liệu bất thường so với pattern bình thường. Ứng dụng: phát hiện gian lận thẻ, phát hiện lỗi sản xuất, bảo mật mạng. Outliers không nhất thiết là anomalies – một giao dịch lớn từ khách hàng VIP không phải gian lận dù là outlier.</p><hr><h3 id="❌-loi-35-cho-rang-ml-khong-can-domain-knowledge" tabindex="-1">❌ Lỗi 35: Cho rằng ML không cần domain knowledge <a class="header-anchor" href="#❌-loi-35-cho-rang-ml-khong-can-domain-knowledge" aria-label="Permalink to &quot;❌ Lỗi 35: Cho rằng ML không cần domain knowledge&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Kỹ sư ML chỉ cần biết kỹ thuật, không cần hiểu lĩnh vực áp dụng.&quot;</p><p><strong>Đúng:</strong> Domain knowledge quan trọng trong ML: chọn features có ý nghĩa, hiểu data quality issues, interpret model predictions trong context thực tế, và tránh spurious correlations (tương quan giả). Doctor-ML team collaboration tốt hơn ML engineer làm một mình trong y tế.</p><hr><h3 id="❌-loi-36-nghi-boosting-va-bagging-la-nhu-nhau" tabindex="-1">❌ Lỗi 36: Nghĩ boosting và bagging là như nhau <a class="header-anchor" href="#❌-loi-36-nghi-boosting-va-bagging-la-nhu-nhau" aria-label="Permalink to &quot;❌ Lỗi 36: Nghĩ boosting và bagging là như nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Boosting và bagging đều là ensemble, như nhau.&quot;</p><p><strong>Đúng:</strong> Bagging (Bootstrap Aggregating): train nhiều model song song trên bootstrap samples, aggregate kết quả. Giảm variance. Random Forest = bagging của decision trees. Boosting: train model tuần tự, mỗi model sửa lỗi của model trước. Giảm bias. AdaBoost, XGBoost = boosting. Hai chiến lược ensemble khác nhau.</p><hr><h3 id="❌-loi-37-nham-tokenization-voi-stemming-trong-nlp" tabindex="-1">❌ Lỗi 37: Nhầm tokenization với stemming trong NLP <a class="header-anchor" href="#❌-loi-37-nham-tokenization-voi-stemming-trong-nlp" aria-label="Permalink to &quot;❌ Lỗi 37: Nhầm tokenization với stemming trong NLP&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tokenization và stemming đều chia nhỏ văn bản, như nhau.&quot;</p><p><strong>Đúng:</strong> Tokenization: chia văn bản thành units (words, subwords, characters). Stemming: rút gọn từ về dạng gốc bằng quy tắc (running → run). Lemmatization: dạng tinh tế hơn, dùng từ điển (better → good). Đây là các bước preprocessing NLP riêng biệt trong pipeline.</p><hr><h3 id="❌-loi-38-cho-rang-ml-model-khong-can-interpretation" tabindex="-1">❌ Lỗi 38: Cho rằng ML model không cần interpretation <a class="header-anchor" href="#❌-loi-38-cho-rang-ml-model-khong-can-interpretation" aria-label="Permalink to &quot;❌ Lỗi 38: Cho rằng ML model không cần interpretation&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Miễn là model dự đoán đúng, không cần hiểu tại sao.&quot;</p><p><strong>Đúng:</strong> Model interpretability quan trọng trong: y tế (bác sĩ cần hiểu tại sao AI chẩn đoán bệnh X), tín dụng (ngân hàng phải giải thích tại sao từ chối vay), pháp lý (GDPR yêu cầu giải thích quyết định tự động ảnh hưởng cá nhân), và debug (hiểu model để cải thiện).</p><hr><h3 id="❌-loi-39-nghi-data-leakage-khong-phai-van-đe-nghiem-trong" tabindex="-1">❌ Lỗi 39: Nghĩ data leakage không phải vấn đề nghiêm trọng <a class="header-anchor" href="#❌-loi-39-nghi-data-leakage-khong-phai-van-đe-nghiem-trong" aria-label="Permalink to &quot;❌ Lỗi 39: Nghĩ data leakage không phải vấn đề nghiêm trọng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Data leakage là lỗi nhỏ, không ảnh hưởng nhiều đến kết quả.&quot;</p><p><strong>Đúng:</strong> Data leakage là lỗi nghiêm trọng: xảy ra khi thông tin từ tương lai (test data) &quot;rò rỉ&quot; vào training process, tạo ra model với performance ảo cao. Ví dụ: dùng feature được tính từ toàn bộ dataset (không tách riêng train/test) trong preprocessing. Model kém trong production dù validation tốt.</p><hr><h3 id="❌-loi-40-nham-ai-fairness-voi-equal-accuracy" tabindex="-1">❌ Lỗi 40: Nhầm AI fairness với equal accuracy <a class="header-anchor" href="#❌-loi-40-nham-ai-fairness-voi-equal-accuracy" aria-label="Permalink to &quot;❌ Lỗi 40: Nhầm AI fairness với equal accuracy&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Model công bằng là model có accuracy như nhau cho mọi nhóm.&quot;</p><p><strong>Đúng:</strong> AI fairness phức tạp hơn: demographic parity (tỷ lệ dự đoán positive bằng nhau), equalized odds (false positive rate bằng nhau), individual fairness (người giống nhau được đối xử giống nhau). Các định nghĩa fairness thường mâu thuẫn với nhau về mặt toán học.</p><hr><h3 id="❌-loi-41-cho-rang-prediction-interval-va-confidence-interval-la-nhu-nhau" tabindex="-1">❌ Lỗi 41: Cho rằng prediction interval và confidence interval là như nhau <a class="header-anchor" href="#❌-loi-41-cho-rang-prediction-interval-va-confidence-interval-la-nhu-nhau" aria-label="Permalink to &quot;❌ Lỗi 41: Cho rằng prediction interval và confidence interval là như nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Confidence interval và prediction interval đều đo độ không chắc chắn.&quot;</p><p><strong>Đúng:</strong> Confidence interval: độ không chắc chắn về parameter (như mean). Prediction interval: độ không chắc chắn về một giá trị tương lai cụ thể. Prediction interval luôn rộng hơn confidence interval vì bao gồm thêm variance của data point riêng lẻ.</p><hr><h3 id="❌-loi-42-nghi-tat-ca-ml-models-đeu-scale-tot-voi-du-lieu-lon" tabindex="-1">❌ Lỗi 42: Nghĩ tất cả ML models đều scale tốt với dữ liệu lớn <a class="header-anchor" href="#❌-loi-42-nghi-tat-ca-ml-models-đeu-scale-tot-voi-du-lieu-lon" aria-label="Permalink to &quot;❌ Lỗi 42: Nghĩ tất cả ML models đều scale tốt với dữ liệu lớn&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng model ML nào cũng được, thêm data thì model tốt hơn.&quot;</p><p><strong>Đúng:</strong> Một số models scale kém: KNN phải tính khoảng cách với toàn bộ training set khi predict (O(n) per query). SVM với kernel có complexity O(n³) khi train. Deep learning scale tốt hơn với nhiều data. Chọn model phù hợp với kích thước dữ liệu và yêu cầu latency.</p><hr><h3 id="❌-loi-43-nham-model-compression-voi-model-pruning" tabindex="-1">❌ Lỗi 43: Nhầm model compression với model pruning <a class="header-anchor" href="#❌-loi-43-nham-model-compression-voi-model-pruning" aria-label="Permalink to &quot;❌ Lỗi 43: Nhầm model compression với model pruning&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Model compression và pruning là như nhau.&quot;</p><p><strong>Đúng:</strong> Pruning: xóa weights nhỏ (gần 0) hoặc neurons ít quan trọng – model nhỏ hơn. Quantization: giảm precision của weights (float32 → int8) – model nhỏ hơn, nhanh hơn. Knowledge distillation: train model nhỏ (student) học từ model lớn (teacher). Ba kỹ thuật compression khác nhau.</p><hr><h3 id="❌-loi-44-cho-rang-ml-khong-can-ethics-review" tabindex="-1">❌ Lỗi 44: Cho rằng ML không cần ethics review <a class="header-anchor" href="#❌-loi-44-cho-rang-ml-khong-can-ethics-review" aria-label="Permalink to &quot;❌ Lỗi 44: Cho rằng ML không cần ethics review&quot;">​</a></h3><p><strong>Sai:</strong> &quot;ML là kỹ thuật thuần túy, không cần review đạo đức.&quot;</p><p><strong>Đúng:</strong> ML trong quyết định high-stakes (tuyển dụng, tín dụng, y tế, tư pháp) cần ethics review: ai là người chịu ảnh hưởng, có thiên kiến không, ai chịu trách nhiệm khi sai. GDPR, AI Act EU, và nhiều luật đang yêu cầu accountability cho AI systems ảnh hưởng đến con người.</p><hr><h3 id="❌-loi-45-nghi-sampling-strategy-khong-quan-trong" tabindex="-1">❌ Lỗi 45: Nghĩ sampling strategy không quan trọng <a class="header-anchor" href="#❌-loi-45-nghi-sampling-strategy-khong-quan-trong" aria-label="Permalink to &quot;❌ Lỗi 45: Nghĩ sampling strategy không quan trọng&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Lấy bất kỳ phần dữ liệu nào làm training set cũng được.&quot;</p><p><strong>Đúng:</strong> Sampling strategy quan trọng với imbalanced data: random sampling có thể lấy quá ít samples của minority class. Stratified sampling đảm bảo tỷ lệ classes được giữ nguyên. SMOTE tạo thêm synthetic samples của minority class. Sampling kém → model bias mạnh về majority class.</p><hr><h3 id="❌-loi-46-nham-ai-voi-đieu-khien-tu-đong-control-systems" tabindex="-1">❌ Lỗi 46: Nhầm AI với điều khiển tự động (control systems) <a class="header-anchor" href="#❌-loi-46-nham-ai-voi-đieu-khien-tu-đong-control-systems" aria-label="Permalink to &quot;❌ Lỗi 46: Nhầm AI với điều khiển tự động (control systems)&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Xe tự lái dùng AI để điều khiển toàn bộ, không có gì khác.&quot;</p><p><strong>Đúng:</strong> Xe tự lái kết hợp: AI/ML (nhận dạng vật thể, dự đoán hành vi), control systems kỹ thuật (PID controllers, MPC điều khiển tay lái/phanh), planning algorithms (path planning), và sensor fusion (kết hợp camera + LIDAR + radar). Không chỉ AI – là hệ thống phức tạp đa lĩnh vực.</p><hr><h3 id="❌-loi-47-cho-rang-model-selection-chi-dua-vao-performance-metrics" tabindex="-1">❌ Lỗi 47: Cho rằng model selection chỉ dựa vào performance metrics <a class="header-anchor" href="#❌-loi-47-cho-rang-model-selection-chi-dua-vao-performance-metrics" aria-label="Permalink to &quot;❌ Lỗi 47: Cho rằng model selection chỉ dựa vào performance metrics&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Chọn model ML tốt nhất chỉ cần nhìn vào accuracy/F1.&quot;</p><p><strong>Đúng:</strong> Model selection cần cân nhắc nhiều yếu tố: performance metrics (accuracy, F1), latency (tốc độ inference), memory footprint (thiết bị nhỏ), interpretability (cần giải thích không), training cost (thời gian/chi phí GPU), và maintenance cost (dễ update không).</p><hr><h3 id="❌-loi-48-nghi-ml-benchmark-ket-qua-truc-tiep-ap-dung-cho-production" tabindex="-1">❌ Lỗi 48: Nghĩ ML benchmark kết quả trực tiếp áp dụng cho production <a class="header-anchor" href="#❌-loi-48-nghi-ml-benchmark-ket-qua-truc-tiep-ap-dung-cho-production" aria-label="Permalink to &quot;❌ Lỗi 48: Nghĩ ML benchmark kết quả trực tiếp áp dụng cho production&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Model đạt SOTA trên ImageNet thì chắc chắn tốt cho ứng dụng thực tế của tôi.&quot;</p><p><strong>Đúng:</strong> Benchmark results đo trên dataset chuẩn, điều kiện kiểm soát. Production thường có: distribution shift (ảnh thực tế khác ảnh training), lower quality input (điện thoại thay vì camera chuyên nghiệp), và edge cases không có trong benchmark. Phải evaluate trên data thực của mình.</p><hr><h3 id="❌-loi-49-nham-ml-deployment-voi-ml-development" tabindex="-1">❌ Lỗi 49: Nhầm ML deployment với ML development <a class="header-anchor" href="#❌-loi-49-nham-ml-deployment-voi-ml-development" aria-label="Permalink to &quot;❌ Lỗi 49: Nhầm ML deployment với ML development&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Sau khi train model xong, deployment chỉ là copy model file vào server.&quot;</p><p><strong>Đúng:</strong> Deployment là giai đoạn riêng biệt phức tạp: containerize model (Docker), set up API endpoint, scale horizontally, monitor performance, handle model versioning, A/B testing, và fallback strategy. MLOps là kỹ năng riêng biệt, không chỉ là sau bước train.</p><hr><h3 id="❌-loi-50-cho-rang-gradient-descent-la-thuat-toan-toi-uu-duy-nhat-trong-ml" tabindex="-1">❌ Lỗi 50: Cho rằng gradient descent là thuật toán tối ưu duy nhất trong ML <a class="header-anchor" href="#❌-loi-50-cho-rang-gradient-descent-la-thuat-toan-toi-uu-duy-nhat-trong-ml" aria-label="Permalink to &quot;❌ Lỗi 50: Cho rằng gradient descent là thuật toán tối ưu duy nhất trong ML&quot;">​</a></h3><p><strong>Sai:</strong> &quot;ML chỉ dùng gradient descent để học.&quot;</p><p><strong>Đúng:</strong> Nhiều thuật toán tối ưu: SGD (Stochastic Gradient Descent), Adam, RMSprop, Adagrad (deep learning). Genetic algorithms, evolutionary strategies (reinforcement learning, neural architecture search). Analytical solutions (Linear Regression, Naive Bayes). Quadratic programming (SVM). Thuật toán tối ưu phụ thuộc vào kiểu bài toán.</p>',279)])])}const m=t(o,[["render",e]]);export{d as __pageData,m as default};
